        LANGUAGE_WRAPPER = 'Let $C = \\{{coeffs_str}\\}$ be a set of {m} positive integer coefficients. Let the function $f(x)$ be defined as $f(x) = \\sum_{c \\in C} \\lfloor c x \\rfloor$. How many integers in the set $\\{1, 2, \\dots, {L}\\}$ can be expressed in the form $f(x)$ for some real number $x$?'

        class _RNGShim:
    def __init__(self, seed: int):
        import random as _random
        self._seed = int(seed)
        self._r = _random.Random(self._seed)

    def random(self): return self._r.random()
    def uniform(self, a, b): return self._r.uniform(a, b)
    def randint(self, a, b): return self._r.randint(a, b)
    def randrange(self, *args): return self._r.randrange(*args)
    def choice(self, seq): return self._r.choice(seq)
    def choices(self, population, weights=None, cum_weights=None, k: int = 1):
        return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
    def sample(self, population, k: int): return self._r.sample(population, k)
    def shuffle(self, x):
        self._r.shuffle(x)
        return x
    def getrandbits(self, k: int): return self._r.getrandbits(k)

        import math

def generator(rng):
    while True:
        m = rng.choice([4, 5])
        coeffs = sorted(rng.sample(range(10, 81), m))

        S = sum(coeffs)
        if not (80 <= S <= 400):
            continue

        q_candidates = set()
        for i in range(m):
            for j in range(i + 1, m):
                g = math.gcd(coeffs[i], coeffs[j])
                if g > 1:
                    for k in range(1, int(g**0.5) + 1):
                        if g % k == 0:
                            if k > 1: q_candidates.add(k)
                            if g // k > 1: q_candidates.add(g // k)

        D2 = []
        for q_cand in sorted(list(q_candidates)):
            num_divisible = sum(1 for c in coeffs if c % q_cand == 0)
            if num_divisible >= 2:
                D2.append(q_cand)

        if not (4 <= len(D2) <= 25):
            continue

        q_L = rng.randint(5, 15)
        r = rng.randint(S // 3, S * 2 // 3)
        L = q_L * S + r

        if L < 1000:
            continue

        coeffs_str = ", ".join(map(str, coeffs))
        return {
            "m": m,
            "coeffs_str": coeffs_str,
            "coeffs": coeffs,
            "L": L,
        }

        import math

def verifier(assign):
    coeffs = assign['coeffs']
    L = assign['L']
    m = assign['m']

    if m != len(coeffs) or not all(c > 0 for c in coeffs):
        return False, None # m must match the length of coeffs, coeffs must be positive

    S = sum(coeffs)
    if S == 0:
        return False, None

    q_L, r = divmod(L, S)

    # Find all denominators q > 1 causing jumps of size >= 2
    q_candidates = set()
    for i in range(m):
        for j in range(i + 1, m):
            g = math.gcd(coeffs[i], coeffs[j])
            if g > 1:
                for k in range(1, int(g**0.5) + 1):
                    if g % k == 0:
                        if k > 1: q_candidates.add(k)
                        if g // k > 1: q_candidates.add(g // k)

    D2 = []
    for q_cand in sorted(list(q_candidates)):
        num_divisible = sum(1 for c in coeffs if c % q_cand == 0)
        if num_divisible >= 2:
            D2.append(q_cand)

    # Find the actual set of missed values in the base period [0, S-m]
    missed_values = set()
    for q_val in D2:
        jump_size = sum(1 for c in coeffs if c % q_val == 0)
        for p in range(1, q_val):
            if math.gcd(p, q_val) == 1:
                f_val = sum((c * p) // q_val for c in coeffs)
                f_val_prev = f_val - jump_size
                for v in range(f_val_prev + 1, f_val):
                    missed_values.add(v)

    # Number of attainable values in [0, S-m]
    # The range of values for x in [0,1) is a subset of [0, S-m].
    V0_size = (S - m + 1) - len(missed_values)

    # Number of attainable values in [0, r]
    missed_in_r = 0
    for v in missed_values:
        if 0 <= v <= r:
            missed_in_r += 1
    V0_cap_r_size = (r + 1) - missed_in_r

    # The set of all attainable values is {nS+k | n>=0, k in V0}.
    # We count those in [1, L].
    # The total count of attainable values in [0,L] is q_L * |V0| + |V0 intersect [0,r]|.
    total_in_0_L = q_L * V0_size + V0_cap_r_size

    # Since f(0)=0 is always attainable and we want positive integers, we subtract 1.
    # This is valid as long as L >= 0.
    if L < 0: return True, 0
    answer = total_in_0_L - 1

    return True, answer


        def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
            """Return dict with assignment/question/answer or raise RuntimeError."""
            start = time.time()
            attempts = 0
            while time.time() - start < timeout_seconds:
                attempts += 1
                rng = _RNGShim(seed + attempts)
                assignment = generator(rng)
                valid, answer = verifier(assignment)
                if valid:
                    question = LANGUAGE_WRAPPER.format(**assignment)
                    return {
                        "assignment": assignment,
                        "question": question,
                        "answer": answer,
                        "attempts": attempts,
                        "elapsed_seconds": time.time() - start,
                    }
            raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

